// Developer-only regeneration. Supply the official extracted RAR 6.24 executable;
// generated test archives are ours, and no RAR executable is redistributed.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{spawnSync}=require('node:child_process');
const hash=data=>crypto.createHash('sha256').update(data).digest('hex');
const repo=path.resolve(__dirname,'../../..'),work=path.join(repo,'work/current/archive-rar-matrix'),writer=path.resolve(process.argv[2]||path.join(work,'writer624/Rar.exe'));
const output=path.resolve(process.argv[3]||path.join(__dirname,'matrix')),input=path.join(work,'input'),oracle=path.join(work,'oracle');
const password='归档-漢字-한글-🔐-é',mtime=new Date('2024-01-02T03:04:06Z');
function run(exe,args,cwd){const result=spawnSync(exe,args,{cwd,encoding:'utf8',timeout:60000,maxBuffer:1024*1024,windowsHide:true});assert(!result.error,String(result.error));assert.equal(result.status,0,result.stdout+'\n'+result.stderr);return result.stdout;}
function files(root,prefix=''){return fs.readdirSync(path.join(root,prefix),{withFileTypes:true}).flatMap(entry=>{const name=prefix+entry.name;return entry.isDirectory()?files(root,name+'/'):[name];}).sort();}
fs.mkdirSync(input,{recursive:true});fs.mkdirSync(output,{recursive:true});assert.equal(fs.readdirSync(output).length,0,'Generate into a new empty directory, then review the fixture replacement.');fs.mkdirSync(oracle,{recursive:true});
const expected=[['说明.txt',6000],['目录/表と漢字.txt',2000],['目录/한글.txt',22000],['emoji-🔐.txt',18000]].map(([name,bytes])=>{const data=Buffer.concat(Array.from({length:Math.ceil(bytes/32)},(_,index)=>crypto.createHash('sha256').update(name+'|'+index).digest())).subarray(0,bytes),target=path.join(input,name);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,data);fs.utimesSync(target,mtime,mtime);return {name,bytes,sha256:hash(data)};}).sort((a,b)=>a.name.localeCompare(b.name,'en'));
const writerSha=hash(fs.readFileSync(writer));assert.equal(writerSha,'a9cec009503d067f241b5eddaea4e42c38edcb0b57c1b46e946c5281b7f1ea21');
const cases=[];for(const version of [4,5])for(const solid of [false,true])for(const headers of [false,true])for(const split of [false,true]){
 const id=`rar${version}-${solid?'solid':'files'}-${headers?'headers':'data'}-${split?'volumes':'single'}`,directory=path.join(output,id);fs.mkdirSync(directory,{recursive:true});
 const archive=path.join(directory,'资料.rar'),args=['a','-cfg-','-y','-idq',`-ma${version}`,solid?'-s':'-s-',`${headers?'-hp':'-p'}${password}`,'-r',...(split?['-v32768b',...(version===4?['-vn']:[])]:[]),archive,'*'];
 run(writer,args,input);const members=files(directory).map(name=>({name,bytes:fs.statSync(path.join(directory,name)).size,sha256:hash(fs.readFileSync(path.join(directory,name)))})),first=members.find(member=>member.name.endsWith('.part1.rar'))||members.find(member=>member.name.endsWith('.rar'));
 assert(first);assert.equal(members.length,split?2:1);const source=path.join(directory,first.name),destination=path.join(oracle,id);fs.mkdirSync(destination,{recursive:true});
 run(writer,['t','-cfg-','-idq','-y',`-p${password}`,source]);run(writer,['x','-cfg-','-idq','-y',`-p${password}`,source,destination+path.sep]);
 assert.deepEqual(files(destination).sort(),expected.map(entry=>entry.name).sort());for(const entry of expected){const data=fs.readFileSync(path.join(destination,entry.name));assert.equal(data.length,entry.bytes);assert.equal(hash(data),entry.sha256);}
 cases.push({id,version,solid,headers,split,naming:split?(version===4?'legacy':'part'):'single',first:first.name,members});
}
const manifest={schema:1,description:'RAR4/5 data/header encryption × solid/non-solid × single/multi-volume; fixed non-ASCII password and Unicode filenames. Independently created and extracted by official RAR, not by One.',writer:{version:'RAR 6.24 x64 (3 Oct 2023)',url:'https://www.rarlab.com/rar/winrar-x64-624.exe',packageSha256:'794481dbbc9009a2565726fb5b4a4ab2fe216ff9edbb08951548ee765de9b4a6',executableSha256:writerSha},generation:{payload:'SHA256(UTF8(filename + separator U+007C + decimal block index)), concatenated and truncated to bytes',fileMtime:mtime.toISOString(),command:['a','-cfg-','-y','-idq','-ma{version}','{-s|-s-}','{-p|-hp}{password}','-r','[-v32768b]','[RAR4 volumes: -vn]','archive','*'],oracleCommands:[['t','-cfg-','-idq','-y','-p{password}','archive'],['x','-cfg-','-idq','-y','-p{password}','archive','destination']]},password,expected,cases};
fs.writeFileSync(path.join(output,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');console.log(`Generated and independently verified ${cases.length} RAR combinations, ${cases.reduce((sum,item)=>sum+item.members.length,0)} volumes.`);
